    readTime: "5 min read",
    excerpt: "Not all debt is created equal. Understanding which debt builds wealth and which destroys it can change the way you make financial decisions.",
    content: `
Most people are told "debt is bad" — but that's an oversimplification. Debt is a tool. Used wisely, it accelerates wealth. Used recklessly, it traps you in a cycle of financial stress.

**Good Debt**

Good debt is borrowed money that has a reasonable interest rate and is used to acquire something that increases in value or generates income:

- **Student loans** (when the degree leads to earnings significantly above the loan amount)
- **Mortgages** — real estate tends to appreciate over time
- **Business loans** — investing in income-generating assets
- **Low-interest auto loans** — if a car is necessary for income generation

**Bad Debt**

Bad debt has high interest rates and is used for depreciating assets or consumption:

- **Credit card debt** at 20–29% APR — this is financial quicksand
- **Payday loans** — can carry effective APRs of 400%+
- **Buy Now, Pay Later (BNPL) missed payments** — can lead to fees and credit damage
- **High-interest personal loans** for discretionary spending

**The Interest Rate Test**

A simple rule: if the interest rate is higher than your expected investment returns (~7%), prioritize paying it off. If it's lower, you may be better off investing the difference.

**Key Takeaway**

Ask yourself: "Is this debt making me money or costing me money?" If it's costing you money at a high rate — attack it aggressively. Use the avalanche method (highest interest first) or snowball method (smallest balance first).
    `
