    title: "Pension vs. 401(k): Understanding Defined Benefit Plans",
    topic: "Retirement",
    tag: "retirement",
    date: "February 14, 2026",
    readTime: "5 min read",
    excerpt: "Pensions are rare today, but if you have one, understanding how it works can change your entire retirement strategy.",
    content: `
Defined benefit plans (pensions) and defined contribution plans (like 401(k)s) both help fund retirement — but they work in fundamentally different ways. Knowing the distinction helps you plan more accurately.

**What Is a Pension?**

A pension, or defined benefit plan, promises you a specific monthly payment in retirement based on a formula — typically tied to your years of service and final salary. Your employer bears the investment risk; you're guaranteed the payment regardless of market performance.

Common formula: Years of service × 1.5%–2.5% × Final average salary
Example: 30 years × 2% × $70,000 = $42,000/year ($3,500/month)

Pensions are most common among:
• Government employees (federal, state, local)
• Teachers and first responders
• Some union workers

**What Is a 401(k)?**

A 401(k) is a defined contribution plan — you and your employer contribute money, it gets invested, and whatever that account grows to is what you have. You bear the investment risk. There's no guaranteed monthly payment.

**Key Differences**

• **Predictability**: Pensions offer a guaranteed income stream; 401(k) outcomes depend on markets and contributions
• **Portability**: 401(k)s move with you when you change jobs; pensions often require vesting (staying employed long enough to earn benefits)
• **Investment control**: 401(k) holders choose their investments; pension participants have no say
• **Inflation protection**: Some pensions include cost-of-living adjustments (COLAs); many don't

**If You Have Both**

Lucky you — this is the most secure retirement position. Your pension covers baseline living expenses; your 401(k) and IRA fund the extras and provide flexibility. Consider a more conservative 401(k) allocation since your pension already provides guaranteed income.

**Key Takeaway**

If you have a pension, understand your vesting schedule, your projected benefit, and whether it includes survivor benefits for a spouse. These details significantly affect your retirement planning.
    `
