    id: 20,
    title: "How to Negotiate Your Salary (And Actually Win)",
    topic: "Income",
    tag: "income",
    date: "November 28, 2025",
    readTime: "6 min read",
    excerpt: "Most people never negotiate their salary — and it costs them tens of thousands of dollars over a career. Here's the script.",
    content: `
Salary negotiation is one of the highest-ROI skills in personal finance. Studies consistently show that people who negotiate earn $5,000–$20,000 more in initial offers, and since raises are typically percentage-based, a higher starting salary compounds over an entire career.

**Why People Don't Negotiate**

• Fear of rejection or seeming greedy
• Not knowing their market value
• Accepting the first offer out of gratitude or excitement
• Believing it's not "allowed"

The reality: employers expect negotiation. Recruiters routinely lowball initial offers anticipating a counter.

**Step 1: Know Your Number**

Research market salary using:
• Glassdoor, Levels.fyi (tech), LinkedIn Salary, Bureau of Labor Statistics
• Talk to people in similar roles — salary transparency benefits everyone
• Factor in your location, experience, and specialization

Identify your target range and your walk-away number.

**Step 2: Time It Right**

Negotiate after you have a written offer. Never give a number first if you can avoid it. When asked your salary expectations, redirect: "I'd love to learn more about the full scope of the role before discussing compensation. What's the budgeted range for this position?"

**Step 3: The Script**

When you have an offer:
"I'm really excited about this opportunity and I'm confident I'd bring strong value to the team. Based on my research and experience, I was hoping we could get closer to [target number]. Is there flexibility there?"

Then — silence. Don't fill the silence. Let them respond.

**Step 4: Negotiate the Full Package**

If the base salary is firm, negotiate:
• Signing bonus
• Extra PTO days
• Remote work flexibility
• Earlier performance review (3 months instead of 12)
• Professional development budget
• Equity or stock options

**Key Takeaway**

The worst they can say is no, and you keep the offer anyway. A 10-minute conversation could be worth $10,000+. Prepare your research, practice your script, and negotiate every single offer.
    `
