    title: "1099 Income and Self-Employment Taxes Explained",
    topic: "Taxes",
    tag: "taxes",
    date: "June 8, 2025",
    readTime: "6 min read",
    excerpt: "Freelance and contract income comes with a separate set of tax obligations most people learn about the hard way. Here's what to know before tax season.",
    content: `
Receiving a 1099 form means you were paid as an independent contractor or freelancer rather than a traditional employee. The income is fully taxable — but the way it's taxed, reported, and paid is very different from W-2 employment income.

**What Is a 1099?**

A 1099-NEC (Nonemployee Compensation) is issued by any business that paid you $600 or more for freelance or contract work in a year. You should receive one by January 31 for the prior tax year. However, you owe taxes on all self-employment income even if you don't receive a 1099 — the IRS doesn't need the form to tax the income.

**The Self-Employment Tax**

This is the biggest tax surprise for new freelancers. As a W-2 employee, you pay 7.65% for Social Security and Medicare; your employer matches it. As a self-employed person, you pay both halves: 15.3% on net earnings.

Example: $50,000 in freelance income
• Self-employment tax: ~$7,065
• Income tax (at 22% bracket, after deductions): additional tax owed
• Total tax obligation is significantly higher than employees at the same income level

The good news: you can deduct half of your self-employment tax as an above-the-line deduction.

**Quarterly Estimated Taxes**

No employer withholds taxes from freelance income. You're responsible for paying the IRS directly four times a year:

• April 15 (Q1: Jan–Mar)
• June 16 (Q2: Apr–May)
• September 15 (Q3: Jun–Aug)
• January 15 (Q4: Sep–Dec)

Missing these payments results in underpayment penalties. A safe rule: pay 100% of last year's tax liability in quarterly installments, or 90% of the current year's expected liability.

**Deductible Business Expenses**

Reduce your taxable self-employment income by tracking:
• Home office (dedicated workspace)
• Equipment (computer, camera, tools)
• Internet and phone (business-use percentage)
• Professional subscriptions and software
• Health insurance premiums (100% deductible for self-employed)
• Retirement contributions (SEP-IRA or Solo 401k — major deductions)

**Key Takeaway**

Start saving for taxes from your first freelance payment. Open a separate savings account and move 25–30% of each payment there immediately. File Schedule C and Schedule SE with your federal return.
    `
