    id: 38,
    title: "Capital Gains Tax: What Investors Need to Know",
    topic: "Taxes",
    tag: "taxes",
    date: "May 28, 2025",
    readTime: "5 min read",
    excerpt: "Selling investments triggers taxes — but how much you owe depends on how long you held them. Strategic timing can save you thousands.",
    content: `
When you sell an investment for more than you paid, the profit is called a capital gain. How that gain is taxed depends primarily on how long you owned the asset — a distinction that can mean paying 0% or up to 37% on the same dollar.

**Short-Term vs. Long-Term Capital Gains**

• **Short-term capital gains**: Assets held 1 year or less. Taxed as ordinary income — the same rate as your wages (10%–37% depending on bracket).
• **Long-term capital gains**: Assets held more than 1 year. Taxed at preferential rates.

2026 Long-Term Capital Gains Tax Rates (estimated):
• 0%: Taxable income up to ~$47,025 (single) / ~$94,050 (married filing jointly)
• 15%: Most middle-income earners
• 20%: Highest earners

This rate difference is enormous. On a $10,000 gain, a single filer in the 22% income tax bracket would pay:
• Short-term: $2,200
• Long-term: $1,500 (15%) — saving $700

**The 0% Capital Gains Rate**

If your taxable income is below the 0% threshold, you owe zero federal tax on long-term gains. This creates a powerful planning opportunity: in years when your income is low (early retirement, career gap, business loss), you can sell appreciated investments and realize gains completely tax-free.

**Capital Losses and Tax-Loss Harvesting**

Capital losses offset capital gains. If you sell an investment at a loss, that loss reduces your gain:
• $10,000 gain - $6,000 loss = $4,000 taxable gain
• Losses exceeding gains can offset up to $3,000 of ordinary income per year
• Excess losses carry forward indefinitely to future tax years

Tax-loss harvesting — deliberately selling losing positions to offset gains — is a valuable strategy in taxable brokerage accounts.

**Wash Sale Rule**

If you sell a security at a loss and repurchase the "substantially identical" security within 30 days before or after the sale, the IRS disallows the loss deduction. To harvest losses legally, wait 31 days or buy a similar-but-not-identical fund.

**Key Takeaway**

Hold investments for at least one year before selling to access preferential long-term rates. Use tax-advantaged accounts (IRA, 401k) for investments you buy and sell frequently to avoid triggering capital gains.
    `
