    id: 44,
    title: "Medical Debt: Your Rights and Options",
    topic: "Debt",
    tag: "debt",
    date: "March 28, 2025",
    readTime: "6 min read",
    excerpt: "Medical debt is the leading cause of bankruptcy in the U.S. — but most people don't know how much negotiating power they actually have.",
    content: `
Medical debt is uniquely different from other types of debt. Unlike a credit card balance or mortgage, medical debt often results from emergencies — situations where you didn't choose the cost and may not have even been conscious to approve it. The good news: you have far more negotiating power with medical debt than most people realize.

**Understand What You Actually Owe**

Before paying anything, request an itemized bill. Medical billing errors are shockingly common — studies suggest 80% of medical bills contain errors. Request your itemized bill in writing and review it line-by-line.

Look for:
• Duplicate charges
• Services billed but not received
• Upcoding (billing for a more expensive service than provided)
• Charges your insurance should have covered

Dispute any errors in writing with both the provider and your insurer.

**Negotiate With the Hospital**

Hospitals — especially nonprofit hospitals — have financial assistance programs (charity care) and are often willing to negotiate bills directly.

• Ask for the financial assistance application. Income thresholds are often higher than people expect (up to 400% of federal poverty level at some hospitals)
• Ask for the "uninsured rate" or "self-pay discount" — can reduce bills 30–50%
• Offer a lump-sum settlement. Hospitals frequently accept 40–60 cents on the dollar for old accounts
• Request a payment plan with zero interest — hospitals are generally required to offer these

**New Protections (2025)**

Starting in 2025, medical debt can no longer appear on credit reports under new federal rules from the CFPB. This removes a major punitive consequence and gives you more time to address bills without credit damage.

**Dealing With Debt Collectors**

If your debt is in collections:
• Request debt validation in writing within 30 days
• Check the statute of limitations in your state — after a period (typically 3–7 years), debts become legally uncollectable
• Never make a payment on old debt without understanding if it resets the clock

**Key Takeaway**

Request your itemized bill, apply for financial assistance before paying, and negotiate directly. Medical debt is the most negotiable type of debt that exists — always explore your options before making full payment or entering a payment plan.
    `
