    id: 53,
    title: "How ICE Affects Our Economy",
    topic: "Economics",
    tag: "economics",
    author: "Nina Tse",
    date: "April 20, 2026",
    readTime: "5 min read",
    excerpt: "The economic consequences of large-scale immigration enforcement extend far beyond the individuals directly affected — potentially impacting GDP, employment, food prices, and tax revenue for all Americans.",
    content: `
**What Is ICE?**

The U.S. Immigration and Customs Enforcement (ICE), established in 2003, enforces immigration laws throughout the United States and at its borders. Under the current administration, ICE's budget and scope of operations have expanded considerably — and economists are tracking significant downstream effects on the broader U.S. economy.

**Impact on GDP**

Perhaps the most striking projection involves America's Gross Domestic Product (GDP) — the broadest measure of a country's economic output. Mass deportations are projected to **reduce U.S. GDP by up to 7% within three years**. For context, the Great Recession of 2007–2009 reduced GDP by only 4%. If accurate, this would represent an economic contraction more severe than the worst financial crisis in a generation.

**Job Losses Extend Beyond Immigrants**

A common assumption is that deportations only affect immigrant workers. The economic reality is more interconnected. According to the Economic Policy Institute, if 4 million people are deported over four years, the projected impact includes:
• **3.3 million fewer employed immigrants**
• **2.6 million fewer employed U.S.-born workers**

This occurs because immigrant labor is embedded throughout supply chains, construction, agriculture, child care, and service industries. When those workers are removed, the businesses and industries that depend on them contract, reducing jobs for everyone.

**Food and Housing Price Inflation**

Economists project that large-scale deportations would also contribute to **price inflation**. Removing 1.3 million immigrant workers could increase prices by 1.5% over three years. Removing 8.3 million workers could push prices up by **9%** — a figure that would exceed peak inflation rates seen during COVID-19, which reached approximately 7.9%.

Many agricultural, construction, and food-processing workers are immigrants. Reducing that labor supply raises production costs, which are then passed on to consumers in the form of higher prices for food, housing, and services.

**Tax Contributions**

U.S. immigrants collectively pay **approximately $580 billion in taxes annually** — contributing to federal, state, and Social Security tax revenues. A 2022 analysis found that immigrants paid $26 billion into Social Security while remaining ineligible to collect many of the benefits they fund. Reducing the immigrant population reduces this tax base, adding fiscal pressure to programs millions of Americans rely on.

**Real-World Example: The Twin Cities**

The economic effects of intensified immigration enforcement are already visible in communities like Minneapolis and the surrounding Twin Cities region. Local small businesses are reporting sharp revenue declines and closures. A survey by the Minneapolis Convention & Visitors Bureau found that **72% of surveyed employers** reported cancellations, postponements, or reduced sales — a direct hit to local economies already navigating post-pandemic recovery.

**The Policy Takeaway**

The economic consequences of immigration enforcement policy are measurable, broad, and felt by everyone — not only by those being deported. Understanding these dynamics is essential for anyone trying to make sense of price changes, labor markets, and fiscal policy in the years ahead.
    `,
