    id: 74,
    title: "When to Close a Credit Card (And When Closing Hurts You)",
    topic: "Credit",
    tag: "credit",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Closing a credit card can actually hurt your credit score — but keeping every card forever isn't always the answer either. Here's how to decide.",
    content: `
Many people assume that closing unused credit cards is good financial hygiene. The reality is more nuanced — and closing the wrong card at the wrong time can ding your credit score significantly.

**Why Closing a Card Can Hurt Your Score**

Two of the five factors in your credit score are directly affected by closing a card:

1. **Credit utilization**: When you close a card, you lose that card's credit limit. If you carry balances on other cards, your utilization ratio increases — potentially significantly. Example: if you have $10,000 total credit limit and $2,000 in balances, your utilization is 20%. Close a card with a $3,000 limit and your utilization jumps to $2,000 out of $7,000 = 28.6%.

2. **Length of credit history**: Older accounts contribute to a longer average credit age. Closing your oldest card can reduce your average account age and lower your score — though closed accounts remain on your report for 10 years, softening this impact.

**When Closing a Card Makes Sense**

• The card charges an annual fee you're not getting value from
• The card has a high interest rate and you carry a balance you'd rather not have available
• You're struggling with overspending and removing access would genuinely help
• The issuer isn't reporting to all three bureaus (making it useless for building credit)

**When to Keep the Card Open**

• It's your oldest card — closing it will eventually reduce your credit age
• You have no other credit and it's your only account
• It has no annual fee — keeping it open costs nothing and preserves your utilization ratio

**The Smart Middle Path**

For cards you don't use but want to keep open: make one small purchase every 3–6 months and pay it off immediately. This prevents the issuer from closing the account due to inactivity while preserving your credit history.

If you must close a card, pay down other balances first to keep utilization low, and don't close multiple cards at once.
    `
