    title: "Dividend Investing: How to Build a Passive Income Stream from Stocks",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "6 min read",
    excerpt: "Dividends are cash payments companies make to shareholders just for holding stock. Here's how dividend investing works and how to build a portfolio that pays you regularly.",
    content: `
Dividend investing is a strategy focused on owning stocks that pay regular cash payments — called dividends — to shareholders. Rather than depending entirely on stock price appreciation, dividend investors collect income from their holdings directly.

**What Is a Dividend?**

A dividend is a portion of a company's profits distributed to shareholders, usually on a quarterly basis. If you own 100 shares of a company that pays a $0.50/share quarterly dividend, you receive $50 every quarter — $200 per year — just for holding the stock.

**Dividend Yield**

Dividend yield is the annual dividend per share divided by the stock price, expressed as a percentage. A stock paying $2/year in dividends and trading at $50/share has a 4% yield.

Average S&P 500 dividend yield: historically around 1.5–2%. High-dividend stocks and funds typically yield 3–6%. Yields above 6–7% warrant caution — they may signal financial instability or a company cutting the dividend.

**Dividend Growth vs. High-Yield**

Two broad approaches:
• **High-yield**: Maximize current income. Good for retirees or income-seekers. Risk: high yields can be unsustainable.
• **Dividend growth**: Focus on companies that consistently increase dividends year over year. Good for long-term compounders. Lower initial yield but growing income over time.

**Dividend Aristocrats**

Companies that have increased their dividend for 25+ consecutive years are called Dividend Aristocrats. Examples include Coca-Cola, Johnson & Johnson, Procter & Gamble, and Realty Income. These companies prioritize consistent shareholder returns across economic cycles.

**Reinvesting Dividends (DRIP)**

Dividend Reinvestment Programs (DRIPs) automatically use your dividend payments to buy additional shares instead of paying cash. This accelerates compounding — your dividends buy more shares, which pay more dividends, which buy more shares.

A $10,000 investment yielding 4% with dividends reinvested at 6% annual price appreciation grows to roughly $57,000 in 20 years. Without reinvestment, the same investment grows to about $32,000 plus $8,000 in dividends collected separately.

**Tax Considerations**

Qualified dividends (most dividends from U.S. stocks) are taxed at capital gains rates (0%, 15%, or 20% depending on income). Non-qualified dividends are taxed as ordinary income. Holding dividend stocks in a Roth IRA eliminates all dividend taxes — an important consideration for income-focused investors.
    `
