    id: 79,
    title: "Tax-Loss Harvesting: How to Turn Investment Losses Into Tax Savings",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "When investments lose value, there's a silver lining: those losses can reduce your tax bill. Tax-loss harvesting is a legal strategy that every investor should understand.",
    content: `
Tax-loss harvesting is the practice of selling investments that have declined in value to realize a capital loss, which can then be used to offset capital gains and reduce your tax liability.

**How It Works**

If you sell an investment at a gain, you owe capital gains tax on the profit. But if you also have investments sitting at a loss, you can sell those to generate an offsetting loss.

Example:
• You sell Stock A for a $5,000 capital gain
• You sell Stock B at a $3,000 capital loss
• Your net taxable gain: $2,000 instead of $5,000

At a 15% capital gains rate, that saves you $450 in taxes ($3,000 × 15%).

**What Happens to the Excess Loss?**

If your losses exceed your gains, you can deduct up to $3,000 of remaining losses against ordinary income per year. Any additional losses carry forward to future tax years indefinitely.

**The Wash-Sale Rule**

The IRS has a critical catch: the wash-sale rule. If you sell a security at a loss and buy the same or a "substantially identical" security within 30 days before or after the sale, the loss is disallowed.

The solution: replace the sold investment with a similar — but not identical — fund. If you sell a large-cap U.S. index fund, you might replace it with a different large-cap fund tracking a similar index. You maintain market exposure while locking in the tax loss.

**When to Harvest Losses**

• Whenever a significant loss exists in a taxable account
• At year-end when you're assessing your overall tax situation
• After market downturns when many positions may be at temporary losses

**Where It Applies**

Tax-loss harvesting only applies to taxable brokerage accounts. Losses inside Roth IRAs, traditional IRAs, and 401(k)s have no tax impact because gains and losses in those accounts aren't taxed annually.

**Robo-Advisors and Automated Harvesting**

Services like Betterment and Wealthfront automate tax-loss harvesting daily, scanning your portfolio for loss opportunities and executing the trades automatically. This is one of the most compelling features of robo-advisors for taxable accounts.
    `
