    title: "ESG Investing: Does Sustainable Investing Actually Deliver Returns?",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "ESG investing — selecting companies based on environmental, social, and governance criteria — has grown massively. But does it actually perform? Here's the honest answer.",
    content: `
ESG stands for Environmental, Social, and Governance — a framework for evaluating companies on factors beyond pure financial metrics. ESG investing has grown from a niche strategy into a multi-trillion dollar category. But it comes with genuine debates about both its effectiveness and its returns.

**What ESG Criteria Look At**

• **Environmental**: Carbon emissions, energy efficiency, water usage, waste management, climate risk
• **Social**: Labor practices, supply chain conditions, diversity and inclusion, community relations, data privacy
• **Governance**: Board composition, executive compensation, shareholder rights, accounting transparency, anti-corruption policies

**How ESG Ratings Work**

Third-party rating agencies (MSCI, Sustainalytics, Bloomberg) assign ESG scores to companies. ESG funds use these ratings to select or exclude holdings. The problem: ratings vary dramatically across agencies. A company might be rated A by one agency and C by another — there's no standardized methodology.

**The Performance Question**

Research on ESG returns is genuinely mixed:
• Some studies show ESG funds matching or slightly outperforming broad market indexes, particularly over 5–10 year periods
• Other studies show underperformance, particularly when excluding sectors like energy that perform well during commodity cycles
• The honest answer: over the long run, the performance gap (positive or negative) appears modest

**The Exclusion Trade-Off**

Many ESG funds exclude tobacco, weapons, fossil fuels, and gambling. During periods when these sectors outperform (energy rallied significantly 2021–2022), ESG funds underperform. This is an intentional trade-off, not a flaw — but investors should understand what they're accepting.

**ESG as a Risk Framework**

Beyond returns, ESG can be viewed as a risk management tool. Companies with poor governance are statistically more likely to face fraud scandals. Companies with poor environmental practices face regulatory risk. Viewed this way, ESG is about identifying companies with better long-term durability — not just values alignment.

**How to Invest in ESG**

Most major fund families offer ESG index funds at low expense ratios (Vanguard ESG U.S. Stock ETF: ESGV, iShares MSCI KLD 400 Social ETF: DSI). These provide broad diversification with ESG screening at minimal additional cost compared to traditional index funds.
    `
