    title: "International Investing: Why Global Diversification Matters",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Most American investors are heavily overweight in U.S. stocks. Here's the case for international diversification — and how to add it to your portfolio simply.",
    content: `
The U.S. stock market makes up roughly 60% of global market capitalization. Yet the average American investor holds 80–90% of their portfolio in U.S. stocks. This is called "home bias" — and it carries real long-term risk.

**The Case for International Investing**

**Diversification benefit**: U.S. and international markets don't move in perfect sync. When the U.S. market struggles, international markets sometimes outperform. This reduces overall portfolio volatility.

**Valuation**: U.S. stocks have historically traded at higher valuations (P/E ratios) than international stocks. If valuations matter — and long-term evidence suggests they do — international stocks may offer better expected returns from current price levels.

**Global growth**: Emerging markets (India, Southeast Asia, parts of Africa) are growing faster than the U.S. economy. International exposure captures this growth.

**Historical periods of international outperformance**: The 2000s (after the dot-com crash) saw international stocks significantly outperform U.S. stocks for a decade. U.S. investors who held no international allocation missed those returns.

**Categories of International Investment**

• **Developed markets**: Europe, Japan, Australia, Canada — stable economies similar to the U.S. (lower risk, lower growth)
• **Emerging markets**: China, India, Brazil, South Korea, Taiwan — faster-growing but higher volatility and political risk
• **Frontier markets**: Smaller, less-developed economies — high risk, often illiquid

**How to Add International Exposure**

The simplest approach: add a single international index fund.

• **Vanguard Total International Stock ETF (VXUS)** — covers 7,000+ stocks across 47 countries
• **iShares Core MSCI Total International Stock ETF (IXUS)** — similar broad exposure
• For emerging markets specifically: **Vanguard FTSE Emerging Markets ETF (VWO)**

A common allocation: 70% U.S. / 30% international. More aggressive investors go 60/40. Passive funds make this effortless and cheap.

**Currency Risk**

International investments involve currency risk — when the dollar strengthens, foreign-denominated assets lose value in dollar terms. Over long periods, currency effects tend to wash out, but they create short-term volatility. Most investors accept this as part of the diversification trade-off.
    `
