    id: 84,
    title: "Small-Cap vs. Large-Cap Stocks: Understanding Market Capitalization",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Market capitalization categorizes stocks by company size — and the category affects risk, return potential, and how the stock behaves in your portfolio.",
    content: `
Market capitalization (market cap) is simply the total value of a company's outstanding shares: stock price multiplied by shares outstanding. It's one of the most basic ways to categorize stocks — and it has real implications for how they behave in your portfolio.

**Market Cap Categories**

• **Mega-cap**: $200B+ (Apple, Microsoft, Nvidia, Amazon)
• **Large-cap**: $10B–$200B (typical S&P 500 companies)
• **Mid-cap**: $2B–$10B
• **Small-cap**: $300M–$2B
• **Micro-cap**: Under $300M (often illiquid, speculative)

**The Risk-Return Trade-Off**

Historically, smaller companies have delivered higher long-term returns than large companies — this is called the "size premium" in academic finance.

Why: Smaller companies have more room to grow. A company worth $500 million can feasibly become worth $5 billion. A company worth $3 trillion has a harder time 10x-ing.

The trade-off: Small-cap stocks are more volatile. During market downturns, they tend to fall harder. They're also less researched (less analyst coverage), meaning mispricings are more common — in both directions.

**Large-Cap Stability**

Large-cap stocks tend to be:
• More stable and less volatile
• More liquid (easier to buy and sell)
• More thoroughly researched by analysts
• Often dividend-paying with established cash flows

They're the core of most portfolios for good reason.

**How to Add Small-Cap Exposure**

Rather than picking individual small-cap stocks (risky and research-intensive), use index funds:
• **Vanguard Small-Cap ETF (VB)** — broad U.S. small-cap exposure
• **iShares Russell 2000 ETF (IWM)** — tracks the Russell 2000 small-cap index
• **Vanguard Small-Cap Value ETF (VBR)** — small-cap with a value tilt (historically strongest returns)

A common approach: hold 70–80% in total market or large-cap funds, 20–30% in small-cap for enhanced long-term return potential with accepted short-term volatility.

**The Academic Case for Small-Cap Value**

Research by Fama and French identified that small-cap value stocks (small companies trading at low valuations) have produced the highest long-term returns of any stock category historically. This "factor investing" approach has become popular among evidence-based investors, though the premium is not guaranteed to persist.
    `
