    id: 93,
    title: "529 Plans: The Tax-Advantaged Way to Save for College",
    topic: "Taxes",
    tag: "taxes",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "529 plans are specifically designed to help families save for education costs tax-free. Here's how they work, who should use them, and a new rule that removes a major objection.",
    content: `
A 529 plan is a tax-advantaged savings account designed for education expenses. Contributions grow tax-free, and withdrawals for qualified education expenses are also tax-free — giving you a powerful compounding advantage over a standard brokerage account.

**How 529s Work**

You contribute after-tax money (no federal deduction, but many states offer state income tax deductions) into a 529 account. The money is invested in mutual funds or ETFs — similar to a 401(k). It grows tax-free, and when used for qualified education expenses, you pay no tax on the growth.

**Qualified Expenses**

• Tuition and fees (college, K-12 up to $10,000/year, trade schools)
• Room and board (if enrolled at least half-time)
• Books, supplies, and technology required for school
• Student loan repayment (up to $10,000 lifetime per beneficiary)

**Non-Qualified Withdrawals**

Withdrawals for non-educational purposes are subject to income tax plus a 10% penalty on the earnings portion only (contributions can always be withdrawn without penalty).

**The 2024 Rule Change: Rollovers to Roth IRA**

Starting in 2024, unused 529 funds can be rolled over to the beneficiary's Roth IRA — up to a lifetime limit of $35,000, subject to annual Roth IRA limits. The account must have been open for at least 15 years. This eliminates the biggest historical objection to 529s: the fear of overfunding with no escape.

**State Tax Benefits**

Over 30 states offer a state income tax deduction or credit for 529 contributions. Some states only offer the deduction for contributions to their own plan; others accept any plan. Check your state's rules — the in-state plan isn't always the best performing option.

**Who Controls the Account**

The parent or donor controls the account and remains in control regardless of the child's age. If one child doesn't use the funds, you can change the beneficiary to another child, yourself, or a future grandchild.

**How Much to Contribute**

Average 4-year college cost (tuition + room/board): $100,000–$200,000 at current prices. Starting early and investing consistently in a stock-heavy allocation (particularly when the child is young) is the most efficient approach. Target-date 529 funds automatically shift to more conservative investments as college approaches.
    `
