    id: 94,
    title: "Charitable Giving and Your Taxes: What Actually Qualifies",
    topic: "Taxes",
    tag: "taxes",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Charitable donations can reduce your tax bill — but only under specific conditions. Here's what qualifies, how to maximize the deduction, and two strategies most donors miss.",
    content: `
Charitable giving feels good and can save on taxes — but the tax benefit depends on how you give, what you give, and how much you give in total. Here's how to make your generosity as tax-efficient as possible.

**The Basic Rule: Itemize to Deduct**

Charitable contributions are only deductible if you itemize your deductions. With the standard deduction at $14,600 (single) and $29,200 (married) in 2025, most Americans don't itemize — meaning most cash donations generate zero tax benefit.

Check: are your total deductions (mortgage interest + state/local taxes up to $10,000 + charitable + other) more than the standard deduction? If not, you'll take the standard deduction anyway and the charitable giving produces no tax saving on its own.

**What Qualifies as a Deductible Donation**

• Cash or check to a 501(c)(3) nonprofit
• Non-cash items (clothing, household goods) at fair market value with a receipt
• Stock donated directly to charity (see "Appreciated Assets" below)
• Mileage driven for volunteer work ($0.14/mile in 2025)

What doesn't qualify: donations to individuals, political campaigns, foreign charities without U.S. 501(c)(3) status, raffle tickets, or the value of your volunteer time.

**Strategy 1: Bunching**

If your normal annual charitable giving doesn't push you over the standard deduction, consider "bunching" — donating two or three years' worth of charitable gifts in a single year. This creates a larger itemized deduction in the bunching year (exceeding the standard deduction) while you take the standard deduction in other years.

**Strategy 2: Donate Appreciated Stock Instead of Cash**

This is one of the most powerful and underused charitable strategies. If you own stock that has appreciated in value, donating it directly to a charity avoids capital gains tax entirely — while you deduct the full fair market value.

Example: You bought stock for $1,000, now worth $5,000. Selling and donating $5,000 cash costs you capital gains tax (perhaps $600). Donating the stock directly: you deduct $5,000 and owe zero capital gains tax. The charity sells the stock tax-free.

**Donor-Advised Funds**

A Donor-Advised Fund (DAF) lets you contribute a large amount in one year (getting the full tax deduction immediately), then distribute to charities over time. This allows bunching while maintaining flexibility about which charities ultimately receive the funds.
    `
