    id: 98,
    title: "House Hacking: How People Live for Free (or Close to It)",
    topic: "Housing",
    tag: "housing",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "House hacking is a real estate strategy where you buy a property, live in one unit, and rent out the others to cover your mortgage. It's one of the fastest paths to free housing and early wealth building.",
    content: `
House hacking is one of the most powerful and underused wealth-building strategies available to young adults. The concept: buy a multi-unit property (duplex, triplex, fourplex), live in one unit, and rent out the others. The rental income covers your mortgage — and sometimes more.

**A Concrete Example**

You buy a duplex for $400,000 using an FHA loan (3.5% down = $14,000 down payment).
• Monthly mortgage (PITI): $2,400
• You rent the other unit for $1,600/month
• Your actual housing cost: $800/month

Instead of paying $1,500–$2,000 in rent for a comparable apartment, you pay $800 — while building equity in a property that appreciates over time.

**Why It Works With FHA Loans**

FHA loans allow 3.5% down payment on properties up to 4 units — as long as you live in one unit as your primary residence. This is one of the few ways to access investment property financing at residential loan rates, which are significantly lower than investment property rates.

Conventional loans can also be used: you get better terms than investment property loans because owner-occupant properties are seen as lower risk.

**Variations of House Hacking**

• **Single-family with a room**: Buy a house, rent out spare bedrooms to roommates. Less rental income, but more privacy and a lower purchase price.
• **ADU (Accessory Dwelling Unit)**: Buy a home with a garage apartment, basement unit, or backyard cottage already built or permit-ready. Rent it out.
• **Short-term rental**: Rent a portion of your home on Airbnb or Vrbo for higher nightly rates. Check local regulations — many cities restrict short-term rentals.

**The Real Costs to Understand**

Being a landlord has costs: repairs, vacancy, tenant screening, potential evictions. Budget for:
• 5–10% vacancy factor
• 1% of property value annually for maintenance
• Property management (8–12% of rent) if you don't self-manage

**The Wealth-Building Equation**

House hacking simultaneously reduces housing costs, builds equity through mortgage paydown, generates appreciation, and provides tax advantages (depreciation on the rental portion). For many people, it's the single best first real estate investment available.
    `
