    id: 101,
    title: "Treasury Bills: The Safest Short-Term Investment You're Probably Not Using",
    topic: "Banking",
    tag: "banking",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "T-bills are short-term government securities backed by the U.S. government that often pay higher yields than savings accounts — with zero credit risk. Here's how to buy them.",
    content: `
Treasury bills (T-bills) are short-term debt obligations issued by the U.S. government, maturing in 4, 8, 13, 17, 26, or 52 weeks. They're widely considered the safest investment in the world because they're backed by the full faith and credit of the U.S. government.

**How T-Bills Work**

T-bills don't pay interest in the traditional sense. Instead, you buy them at a discount to face value and receive the full face value at maturity. The difference is your return.

Example: You pay $9,800 for a 26-week T-bill with a face value of $10,000. At maturity, you receive $10,000 — a $200 gain on a $9,800 investment (approximately 4% annualized).

**Why They Can Beat Savings Accounts**

During periods of elevated federal funds rates, T-bill yields often exceed what online savings accounts pay. Because T-bill yields are set at weekly auction based on market demand, they respond quickly to interest rate changes — unlike bank savings rates that move more slowly.

**Tax Advantage**

T-bill interest is subject to federal income tax but exempt from state and local income taxes. For residents of high-tax states like California, New York, or New Jersey, this exemption makes T-bills meaningfully more attractive than equivalent savings accounts on an after-tax basis.

**How to Buy T-Bills**

**Option 1: TreasuryDirect.gov** — buy directly from the government, no fees. Minimum $100. Purchase at weekly auctions. Slightly less convenient to manage.

**Option 2: Brokerage account** — Fidelity, Schwab, and Vanguard allow T-bill purchases on their platforms. More flexibility, easier management, though some platforms charge small transaction fees.

**Option 3: Treasury ETFs** — funds like SGOV (iShares 0-3 Month Treasury Bond ETF) or BIL (SPDR Bloomberg 1-3 Month T-Bill ETF) hold rolling T-bills. No auction timing required, instant liquidity, very low expense ratios.

**When T-Bills Make Sense**

• Cash you won't need for 1–12 months that's sitting in a low-yield savings account
• Conservative investors who want government-guaranteed returns above savings rates
• High-income earners in high-tax states who benefit most from the state tax exemption
    `
