    id: 103,
    title: "FDIC Insurance: Exactly How Your Bank Deposits Are Protected",
    topic: "Banking",
    tag: "banking",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "FDIC insurance protects your bank deposits if a bank fails — but it has limits and rules most people don't fully understand. Here's exactly how it works.",
    content: `
The Federal Deposit Insurance Corporation (FDIC) is a government agency that insures deposits at member banks. If an FDIC-insured bank fails, depositors are protected up to the coverage limits — the government guarantees they'll get their money back.

**The Basic Coverage Limit**

$250,000 per depositor, per institution, per ownership category.

Each of those three factors matters.

**Per Depositor**

You have $250,000 in protection at each bank you use. If you have $300,000 at one bank in a single account, $50,000 is uninsured and at risk.

**Per Institution**

Having accounts at multiple banks multiplies your protection. $250,000 at Bank A and $250,000 at Bank B = $500,000 fully insured.

**Per Ownership Category**

This is where FDIC insurance becomes powerful. Each ownership category is separately insured:
• **Single accounts**: $250,000
• **Joint accounts**: $250,000 per owner ($500,000 for a two-person joint account)
• **Retirement accounts (IRA, Roth IRA)**: $250,000 per depositor per institution, separate from your personal accounts
• **Trust accounts**: Can extend coverage significantly for accounts with multiple beneficiaries

A married couple at one bank can potentially insure:
• $250,000 in individual accounts each ($500,000 total)
• $500,000 in a joint account ($250,000 × 2 owners)
• $250,000 each in IRAs ($500,000 total)

That's $1.5 million+ fully insured at a single institution when organized correctly.

**What FDIC Does NOT Cover**

• Stocks, bonds, mutual funds, ETFs — including those held at a bank's brokerage arm
• Life insurance products and annuities sold through banks
• Safe deposit box contents
• Cryptocurrency

**How to Check If Your Bank Is FDIC Insured**

Look for the FDIC logo on the bank's website or use the FDIC BankFind tool at FDIC.gov. Credit unions have their own equivalent: NCUA insurance, with the same $250,000 limits.

**What Happens in a Bank Failure**

The FDIC takes over the failed bank, typically over a weekend, and usually transfers accounts to another bank by the following Monday. In practice, most customers experience no interruption in access to insured funds.
    `
