    id: 107,
    title: "How to Negotiate Equity in a Job Offer",
    topic: "Income",
    tag: "income",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Equity can be worth far more than the salary on a job offer — or far less. Here's how to evaluate it, what to ask for, and how to negotiate effectively without leaving money on the table.",
    content: `
When negotiating a job offer that includes equity, most candidates focus almost entirely on salary — and leave significant value on the table. Equity negotiation requires different skills and information than salary negotiation.

**Evaluating the Equity Component**

Before negotiating, you need to understand what you're actually receiving.

**For public company RSUs:**
• Calculate the current dollar value (shares × current stock price)
• Understand the 4-year vesting schedule — what vests when
• Factor in taxes: RSUs vest as ordinary income

**For private company stock options:**
The value is unknown and depends entirely on future outcomes. Key questions to ask:
• What is the current preferred share price (from the last funding round)?
• What was the most recent 409A valuation (the fair market value of common shares)?
• What percentage of the company do your options represent (not just the number of shares)?
• What is the strike price?
• What is the company's current revenue and growth rate?

A company with 10 million shares outstanding offering you 100,000 shares = 1% equity. A different company offering the same 100,000 shares but with 200 million outstanding = 0.05%. The number of shares is meaningless without knowing the total outstanding.

**What to Negotiate**

• Total grant size: Ask for more shares or RSUs
• Strike price: Already set by the 409A; not negotiable
• Vesting schedule: Request a shorter cliff (6 months vs 1 year) or faster vesting
• Acceleration clauses: Request "double-trigger acceleration" — if the company is acquired AND you're laid off, all remaining equity vests immediately

**How to Ask for More Equity**

"I'm very excited about the role and the company. The salary is competitive, but I was hoping to discuss the equity component. Based on my research into compensation at comparable companies at this stage, and the value I'd bring to this role, I'd like to explore whether there's flexibility to increase the equity grant."

Frame it around value you'll create — not personal financial need. Always have a target number in mind before the conversation.

**The Vesting Cliff: Critical for Short Stays**

If you leave before the 1-year cliff in a standard 4-year/1-year vesting schedule, you receive zero equity regardless of how much you contributed. This is intentional — it incentivizes staying. Factor the cliff into your decision: if you're not confident you'll stay at least 12 months, unvested equity has zero current value.
    `
