    id: 108,
    title: "Unemployment Insurance: How It Works and What You Need to Know",
    topic: "Income",
    tag: "income",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Unemployment insurance is a safety net most workers pay into but few understand until they need it. Here's how it works, who qualifies, and how to file effectively.",
    content: `
Unemployment insurance (UI) provides temporary income replacement to workers who lose their jobs through no fault of their own. It's funded by payroll taxes paid by employers and administered by individual states.

**Who Qualifies**

To receive unemployment benefits, you typically must:
• Have worked a minimum amount during a "base period" (usually the first four of the last five completed calendar quarters)
• Have earned enough wages during the base period (specific thresholds vary by state)
• Be unemployed through no fault of your own (layoff, company closure, reduction in force)
• Be actively seeking new employment
• Be available and able to work

**Who Does NOT Qualify**

• You quit voluntarily (exceptions exist for constructive dismissal, hostile work environments, following a spouse, serious medical conditions)
• You were fired for misconduct
• Independent contractors and gig workers (though pandemic legislation temporarily extended coverage — check current rules in your state)
• Self-employed individuals (no UI, though this also varied during COVID-19)

**How Much You'll Receive**

Benefits vary by state but typically replace 40–60% of your pre-unemployment weekly wage, up to a state maximum. The national average is around $450–$600/week. Benefits typically last 26 weeks, though some states offer less.

**How to File**

1. File immediately after your last day — don't wait. There's often a 1-week waiting period before benefits begin; filing late extends that delay.
2. File with your state's unemployment agency online (faster) or by phone. Search "[your state] unemployment benefits" for the official portal.
3. You'll need: employer information, dates of employment, reason for separation, earnings information
4. Certify weekly or biweekly that you're still unemployed and actively searching for work

**Important: UI Benefits Are Taxable**

Unemployment insurance benefits are taxable as ordinary income at the federal level (and most states). You can choose to have taxes withheld (10% flat rate) during the year to avoid a surprise bill at tax time. Always withhold.

**If You're Denied**

If your claim is denied, appeal. Many legitimate claims are initially denied but reversed on appeal. The appeals process usually involves a phone hearing where you can present your case.
    `
