    id: 109,
    title: "Disability Insurance: The Coverage Most People Are Missing",
    topic: "Insurance",
    tag: "insurance",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Your ability to earn income is your most valuable financial asset. Disability insurance protects it if illness or injury prevents you from working — yet most people have far less coverage than they think.",
    content: `
The statistics are stark: one in four 20-year-olds will experience a disabling condition before they retire. Yet disability insurance — coverage that replaces your income if you can't work — is among the most underowned types of coverage.

**What Disability Insurance Does**

If you become ill or injured and cannot work, disability insurance pays a percentage of your income (typically 60–70%) until you recover or reach the end of the benefit period.

**Short-Term vs. Long-Term Disability**

**Short-term disability (STD)**: Covers a brief period of inability to work, typically 3–6 months. Benefit: starts quickly (often after a 7–14 day elimination period). Many employers offer this as a benefit.

**Long-term disability (LTD)**: Covers extended periods of disability — benefits typically begin after short-term disability ends (around 90 days) and can continue for several years, to age 65, or for life depending on the policy.

**The Coverage Gap in Employer Plans**

Many employers offer group disability insurance, but these plans often provide insufficient coverage:
• Benefits are typically 60% of salary — already a significant income cut
• Benefits may be capped at $5,000–$10,000/month regardless of your salary
• Group disability benefits are taxable if the employer pays the premiums
• Coverage ends when you leave the employer
• Group definitions of "disability" may be stricter than individual policies

**What to Look For in a Policy**

• **Own-occupation definition**: Pays if you can't perform your specific occupation — the gold standard. A surgeon who loses hand function is disabled under this definition even if they can do other work.
• **Any-occupation definition**: Only pays if you can't do any work at all — much harder to qualify for benefits
• **Elimination period**: How long you wait before benefits start (90 days is common; longer periods cost less)
• **Benefit period**: How long benefits last (to age 65 is ideal)
• **Benefit amount**: 60–70% of gross income is standard

**How to Get Coverage**

1. First, maximize any employer-provided coverage (and consider paying the premiums yourself so benefits are tax-free)
2. If your employer offers voluntary supplemental coverage, this is typically the cheapest way to increase coverage
3. For high earners or self-employed individuals: individual disability policies from companies like Guardian, MassMutual, or Principal offer stronger own-occupation protection

**The Self-Employed Case**

Self-employed individuals have no employer group plan — they must purchase individual coverage. This is even more critical: there's no employer sick leave, no workers' comp, and no group plan to fall back on. An individual disability policy is essential protection.
    `
