    id: 123,
    title: "Inheriting Money: What to Do in the First 30 Days",
    topic: "Economics",
    tag: "economics",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Receiving an inheritance brings both grief and significant financial decisions — often at the worst possible time. Here's a practical guide to navigating an inheritance wisely.",
    content: `
Inheriting money arrives during one of life's most difficult moments. The combination of grief and sudden financial decisions creates risk — people frequently make costly mistakes with inheritances by acting too quickly or too slowly.

**The First 30 Days: Do Almost Nothing**

Except for time-sensitive legal requirements (probate deadlines, estate account management), do not make major financial decisions in the first 30 days. Do not quit your job, buy a house, or invest a large sum while still processing grief and the logistics of an estate.

Park inherited cash in a high-yield savings account or money market fund while you develop a thoughtful plan.

**Understand What You're Receiving**

Inheritances come in multiple forms, each with different rules:

**Cash and bank accounts**: Generally transferred directly after probate (or immediately if accounts had transfer-on-death beneficiaries). No income tax on the inheritance itself.

**Investment accounts**: You receive a "stepped-up cost basis" — your tax basis becomes the value at the date of death, not what the original owner paid. This means you can sell immediately with no capital gains tax on pre-death appreciation.

**Retirement accounts (inherited IRA)**: The rules changed significantly with the SECURE Act (2019). Non-spouse beneficiaries must distribute the account within 10 years. Distributions are taxable income — taking large distributions in high-income years can push you into higher brackets. Strategic timing of distributions matters.

**Real estate**: You receive a stepped-up basis here too. Immediately after inheritance, a sale will typically generate little or no capital gains tax. The longer you hold, the more future appreciation becomes taxable.

**Estate and Inheritance Taxes**

Federal estate tax applies only to estates over $13.6 million (2024). Most people don't pay it. However, six states have separate inheritance taxes (Iowa, Kentucky, Maryland, Nebraska, New Jersey, Pennsylvania) that may apply depending on your relationship to the deceased.

**Making a Plan**

After the first 30 days:
1. Get a full picture of what you've inherited and its tax implications
2. Determine if any debts should be paid off (high-interest credit cards, student loans)
3. Assess whether your emergency fund, insurance coverage, and retirement savings need strengthening
4. Work with a fee-only financial advisor for large inheritances before making major investment decisions
5. Consider whether the inheritance aligns with or changes your long-term financial goals
    `
