    id: 129,
    title: "How the Federal Reserve Controls Interest Rates (And Why It Matters for You)",
    topic: "Economics",
    tag: "economics",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "The Federal Reserve's interest rate decisions ripple through the entire economy — affecting your mortgage, savings account, stock portfolio, and job market. Here's how it all connects.",
    content: `
The Federal Reserve (the Fed) is the central bank of the United States. Its most watched function is setting the federal funds rate — the interest rate at which banks lend money to each other overnight. This single number influences nearly every borrowing and lending rate in the country.

**How the Federal Funds Rate Works**

Banks are required to hold a certain amount of reserves. They frequently lend excess reserves to each other overnight to meet requirements. The rate on these short-term interbank loans — the federal funds rate — is what the Fed targets.

The Fed doesn't force banks to use a specific rate; it influences it through open market operations (buying or selling government securities) to increase or decrease the money supply.

**The Dual Mandate**

The Fed has two official goals:
• Maximum employment
• Stable prices (targeting approximately 2% annual inflation)

These goals often conflict. Low interest rates stimulate employment but can cause inflation. High rates combat inflation but can cause unemployment.

**How Rate Changes Affect You**

**Savings accounts and CDs**: When the Fed raises rates, savings account yields and CD rates generally rise. When rates fall, they drop. High-yield savings accounts and money market funds move closely with the federal funds rate.

**Mortgages**: 30-year fixed mortgage rates don't directly track the fed funds rate — they more closely follow the 10-year Treasury yield. But when the Fed raises short-term rates aggressively, long-term rates often rise too. A 1% rise in mortgage rates on a $400,000 mortgage increases monthly payments by roughly $240.

**Credit cards**: Variable-rate credit cards typically move directly with the prime rate (which tracks the fed funds rate). Higher rates mean higher interest on carried balances.

**Stock market**: Lower rates make stocks more attractive relative to bonds (higher bond yields compete with stocks). Rising rates can pressure stock valuations, particularly for growth stocks whose future earnings are discounted more heavily.

**Business activity**: Higher borrowing costs make business expansion more expensive, potentially slowing hiring and economic growth. Lower rates stimulate borrowing and investment.

**Why the Fed's Decisions Move Markets**

Because rate decisions touch everything simultaneously — borrowing costs, asset valuations, currency value, consumer spending — even anticipated changes cause large market movements. The Fed's communication (FOMC statements, press conferences, meeting minutes) is studied intensely for signals about future rate direction.
    `
