    id: 130,
    title: "Investing During a Recession: What Market History Actually Shows",
    topic: "Economics",
    tag: "economics",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Recessions feel catastrophic but historically represent significant buying opportunities. Here's what market history shows about investing during economic downturns — and what most people get wrong.",
    content: `
During a recession, every financial headline feels dire. Markets fall, unemployment rises, and the natural human instinct is to stop investing — or sell everything. This instinct, while understandable, is exactly wrong from a long-term perspective.

**What a Recession Actually Is**

A recession is defined as two consecutive quarters of negative GDP growth, often accompanied by rising unemployment and decreased consumer spending. They're normal features of the economic cycle. Since World War II, the U.S. has experienced 13 recessions — averaging one every 5–6 years.

The average recession lasts approximately 10 months. The longest (Great Recession): 18 months. Most are shorter.

**What Markets Do During and After Recessions**

Stock markets typically fall during recessions — but they lead the economy, meaning they often start falling before the recession officially begins and start recovering before it officially ends.

Key historical data:
• The S&P 500 average return in the 12 months after a recession ends: approximately 40–50%
• Investors who sold at the bottom and waited to "feel safe" before re-entering typically missed most of the recovery
• Those who continued investing through the downturn captured the full recovery

**The Behavioral Error of Stopping**

During the 2008–2009 financial crisis, the S&P 500 fell approximately 57% from peak to trough. Many investors sold. By March 2013, the market had fully recovered. By 2020, it was 300%+ above the 2009 low.

Investors who stopped investing or sold in early 2009:
• Lost the recovery gains
• Bought back at higher prices later
• Suffered the worst of both worlds

**What to Do During a Recession**

• **Continue automatic contributions**: Dollar-cost averaging means buying more shares when prices are lower — the mechanical opposite of buying high
• **Rebalance into equities**: If stocks fall and bonds hold, rebalancing moves money into stocks at lower prices
• **Hold sufficient cash**: Having an emergency fund means you never have to sell investments at depressed prices to cover expenses
• **Avoid individual stock bets**: Recessions cause real business failures; diversification protects against picking the wrong survivor
• **Tax-loss harvest**: Market downturns create tax-loss harvesting opportunities that reduce your future tax bills
    `
