    id: 138,
    title: "Pay Off Debt or Invest? A Framework for Deciding",
    topic: "Debt",
    tag: "debt",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Should you pay down debt or invest that extra money? The mathematically correct answer depends on interest rates — but the right answer for you includes more than just math.",
    content: `
One of the most common personal finance questions: I have extra money each month. Should I pay down debt or invest it? The answer isn't one-size-fits-all — it depends on the type of debt, the interest rate, and your psychological relationship with debt.

**The Mathematical Framework**

Compare your debt's interest rate to your expected investment return.

If debt interest rate > expected investment return: Pay the debt first.
If expected investment return > debt interest rate: Invest first.

Historical average stock market return: approximately 7–10% annually (nominal), 5–7% inflation-adjusted.

**The Decision by Interest Rate**

**High-interest debt (above 7–8%): Pay off first**
Credit cards at 18–25% APR, payday loans, personal loans above 10%. No investment reliably beats these rates. Paying off high-interest debt is a guaranteed return equal to the interest rate.

**Medium-interest debt (4–7%): Judgment call**
Student loans and some personal loans in this range. Arguments for both directions:
• Paying off provides guaranteed, risk-free return at that rate
• Investing in diversified equities may outperform over long periods — but with uncertainty

Many people split in this range: pay extra on debt while also investing.

**Low-interest debt (below 4%): Invest**
Mortgages at 3–4%, subsidized student loans at 2–3%. Historically, diversified stock investing has beaten these rates over most 10+ year periods. Investing the difference is typically the right mathematical choice.

**Always Do These First**

Before the pay-off-vs-invest question even applies:
1. Get the full 401(k) employer match (guaranteed 50–100% return)
2. Build a starter emergency fund ($1,000–3,000)
3. Pay off any debt above 10% interest rate

**The Psychological Factor**

Debt creates stress. For many people, the peace of mind from becoming debt-free has real value that isn't captured in interest rate math. If debt weighs on you constantly, paying it off at an interest rate slightly below expected investment returns may be the right choice anyway — because you'll make better decisions (sleep better, think more clearly, take more appropriate investment risk) without the psychological burden.

A practical middle path: split extra cash between debt paydown and investing, especially in the medium-interest range. You make progress on both without sacrificing either.
    `
