    id: 139,
    title: "How to Read Your Pay Stub Line by Line",
    topic: "Income",
    tag: "income",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Your pay stub contains crucial information about your compensation and deductions — but most people don't understand every line. Here's a complete breakdown of what each item means.",
    content: `
Your pay stub is a detailed record of your earnings and deductions for each pay period. Understanding every line helps you catch errors, optimize your withholding, and understand exactly where your money goes before it reaches your bank account.

**Earnings Section**

**Gross pay**: Your total earnings before any deductions. If you're salaried at $70,000/year and paid biweekly (26 pay periods), your gross pay per check is $2,692.31.

**Regular hours/overtime**: For hourly employees, shows hours worked at regular and overtime rates.

**YTD (Year-to-Date)**: Cumulative total for the year to date. Useful for tracking total earnings and ensuring W-2 accuracy at tax time.

**Tax Withholding Section**

**Federal income tax**: Withheld based on your W-4 elections (filing status, additional withholding, exemptions). If your withholding is too high, you get a refund; too low, you owe in April.

**State income tax**: Withheld for your state (if applicable). Not all states have income tax.

**Social Security tax**: 6.2% of gross wages (on wages up to $176,100 in 2025). Your employer matches this.

**Medicare tax**: 1.45% of all wages. An additional 0.9% applies to wages over $200,000 (single) or $250,000 (married).

**FICA total**: Social Security + Medicare combined. Together you pay 7.65% on eligible wages.

**Pre-Tax Deductions** (Reduce Your Taxable Income)

**401(k) contribution**: Reduces your federal and state taxable income. Seeing this on your stub means your retirement contribution is coming out pre-tax.

**Health insurance premium**: Your share of employer-sponsored health insurance. Usually pre-tax through a Section 125 cafeteria plan.

**HSA/FSA contribution**: Pre-tax health savings contributions.

**Dental/vision premiums**: Often pre-tax as well.

**Post-Tax Deductions** (Don't Reduce Taxable Income)

**Roth 401(k) contribution**: After-tax retirement contribution.

**Life insurance premiums over $50,000**: Required by IRS.

**Wage garnishments**: Child support, student loan garnishments, tax levies.

**Net Pay**

Your take-home pay: Gross pay minus all taxes and deductions. This is what hits your bank account.

**Check for Errors**

Review for: correct pay rate, accurate hours, correct benefit deductions, correct withholding amounts. Payroll errors happen more often than most people realize — especially around address changes, benefit elections, and W-4 updates.
    `
