    id: 148,
    title: "Gross vs. Net Income: Why the Difference Matters for Every Financial Decision",
    topic: "Income",
    tag: "income",
    date: "October 26, 2026",
    readTime: "3 min read",
    excerpt: "Gross income and net income are two very different numbers — and confusing them is one of the most common financial mistakes. Here's the difference and why it matters for budgeting, loans, and benefits.",
    content: `
Gross income and net income are not interchangeable — they represent very different realities, and financial decisions made with the wrong number lead to real problems.

**Gross Income**

Gross income is your total earnings before any deductions: taxes, retirement contributions, health insurance premiums, and other withholdings.

If your salary is $70,000/year, your gross pay is $70,000 regardless of what you take home.

Gross pay per paycheck (biweekly): $70,000 ÷ 26 = $2,692.31

**Net Income (Take-Home Pay)**

Net income is what actually hits your bank account after all deductions.

From that $2,692.31 gross paycheck, subtract:
• Federal income tax: ~$350–400
• State income tax (varies by state): ~$100–200
• Social Security (6.2%): $167
• Medicare (1.45%): $39
• Health insurance premium: ~$150–300
• 401(k) contribution (if any): variable

Net pay: often $1,700–$2,100 on a $70,000 salary — approximately 60–75% of gross.

**Why This Matters**

**Budgeting**: Always budget from net income, not gross. New employees frequently set up budgets using their salary before they've received a paycheck — then their first check is $500 less than expected because they didn't account for taxes and benefits.

**Loan approval**: Lenders calculate debt-to-income ratios using gross income. A mortgage approval uses gross income even though you make payments with net income. Make sure your housing costs are manageable against net income, not just the lender's gross income calculation.

**Benefits communication**: Employers often quote benefit values in gross terms ("$500/month health insurance value"). The actual cost to you is the employee share of the premium, deducted from gross pay (pre-tax).

**When "Gross" Is Used**

• Job offers and salary negotiations: always gross annual salary
• Loan applications and debt-to-income calculations: gross income
• Tax calculations: gross income as the starting point (adjusted to AGI, then taxable income)

**When "Net" Is What Matters**

• Your actual spending budget: net pay
• Calculating how much you can actually afford: net
• Side hustles and freelance income (before you estimate quarterly taxes owed): consider 25–30% set aside for taxes on top of what you earn
    `
