    excerpt: "Dollar-cost averaging — investing a fixed amount on a regular schedule regardless of market conditions — is one of the most powerful and behaviorally sound investment strategies available to ordinary investors.",
    content: `
Dollar-cost averaging (DCA) is the practice of investing a fixed dollar amount at regular intervals — weekly, biweekly, or monthly — regardless of what the market is doing. It's the default strategy for most Americans who contribute to a 401(k) through payroll deductions, often without knowing it.

**How It Works**

Suppose you invest $500/month in an S&P 500 index fund. Some months, prices are high — your $500 buys fewer shares. Other months, prices are low — your $500 buys more shares. Over time, you automatically buy more shares when they're cheap and fewer when they're expensive.

Example over three months:
• Month 1: Price $50/share → buy 10 shares
• Month 2: Price $25/share (market drops) → buy 20 shares
• Month 3: Price $40/share (recovery) → buy 12.5 shares

Total: 42.5 shares for $1,500 = average cost of $35.29/share
But if you'd tried to time it and invested $1,500 in Month 1 at $50: 30 shares

DCA resulted in more shares for the same money.

**Why DCA Works Behaviorally**

The deeper advantage of DCA isn't mathematical — it's behavioral. The biggest investment returns killer is panic selling during downturns and missing the recovery.

DCA creates a structure that removes decision-making from the equation. When markets fall, you don't have to decide whether to invest; the automatic contribution just buys more shares at lower prices. When markets rise, you don't have to decide whether to sell; the plan keeps running.

**DCA vs. Lump Sum**

Historical data shows that lump sum investing (investing all available money immediately) outperforms DCA approximately 2/3 of the time over 10-year periods — because markets tend to rise over time, and money invested earlier has more time to compound.

However: this assumes you can invest a lump sum and leave it alone during the subsequent volatility. For most people, DCA's behavioral advantages — reducing the temptation to time the market, preventing panic from a poorly timed lump sum — make it the practically superior strategy.

**Implementing DCA**

Set up automatic monthly contributions to:
• 401(k): payroll deductions automate this
• Roth IRA: schedule a monthly auto-contribution at Fidelity, Vanguard, or Schwab
• Taxable brokerage: set up automatic recurring investments on most platforms

Once automated, you can stop thinking about market conditions entirely.
    `
