    title: "REITs: How to Invest in Real Estate Without Being a Landlord",
    topic: "Investing",
    tag: "investing",
    date: "October 26, 2026",
    readTime: "4 min read",
    excerpt: "Real Estate Investment Trusts let you own a fractional stake in commercial real estate portfolios — with the liquidity of a stock and without the headaches of being a landlord. Here's what they are and when they make sense.",
    content: `
Real Estate Investment Trusts (REITs) are companies that own income-producing real estate — apartment complexes, office buildings, shopping centers, hospitals, data centers, warehouses — and must distribute at least 90% of taxable income to shareholders as dividends.

They trade on stock exchanges like any other stock, making real estate investment accessible with as little as one share ($20–$100 for many REITs).

**Types of REITs**

**Equity REITs**: Own and operate properties, earning income from rent. The most common type. Examples: apartment REITs (AvalonBay), industrial REITs (Prologis, which owns warehouses for Amazon and FedEx), healthcare REITs (Welltower), data center REITs (Equinix).

**Mortgage REITs (mREITs)**: Lend money to real estate owners or invest in mortgage-backed securities, earning income from interest. More sensitive to interest rate changes. Higher dividend yields, but more volatile.

**REIT ETFs**: Index funds holding dozens or hundreds of individual REITs. The simplest way to get diversified real estate exposure (VNQ from Vanguard, SCHH from Schwab, XLRE).

**Why REITs?**

**Income**: The 90% distribution requirement creates higher dividend yields than most stocks. Many REITs yield 3–6% annually, some more.

**Inflation hedge**: Real estate rents and property values tend to rise with inflation over time.

**Diversification**: Real estate returns have historically had low correlation with stocks and bonds, providing portfolio diversification.

**Liquidity**: Unlike direct real estate ownership, REIT shares can be sold in seconds during market hours.

**No landlord headaches**: No tenants, no maintenance calls, no property management.

**The Drawbacks**

**Tax inefficiency**: REIT dividends are mostly taxable as ordinary income (not qualified dividends), unlike most stock dividends. Hold REITs in tax-advantaged accounts (IRA, 401k) when possible.

**Interest rate sensitivity**: When rates rise, REITs often fall in price because their debt costs increase and bond yields compete with their dividends.

**Sector concentration**: Investing in individual REITs concentrates in one property type; REIT ETFs provide broader diversification.

**How to Invest in REITs**

• For most investors: Add a REIT ETF (VNQ, SCHH, or equivalent) as 5–15% of your portfolio, held in a tax-advantaged account
• For income-focused investors: Individual REIT selection based on property type, balance sheet quality, and dividend growth history
• Avoid mREITs unless you understand interest rate risk
    `
