    title: "Your Financial Independence Number: How to Calculate When You Can Retire",
    topic: "Retirement",
    tag: "retirement",
    date: "October 26, 2026",
    readTime: "5 min read",
    excerpt: "Financial independence means having enough invested that your portfolio can sustain your lifestyle indefinitely. Here's how to calculate your number — and how to reach it.",
    content: `
Financial independence (FI) is the point at which your invested assets generate enough returns to cover your living expenses without needing to work for income. Your "FI number" is the investment portfolio size that makes this possible.

**The 4% Rule Explained**

The most widely used framework for retirement sustainability is the 4% rule, derived from the Trinity Study. It states that a portfolio with a 50–75% stock allocation can sustain annual withdrawals of 4% of the initial balance, adjusted for inflation, for at least 30 years across historical market conditions.

At 4% withdrawal rate: you need 25× your annual expenses to be financially independent.

**Calculating Your Number**

Step 1: Determine your annual spending.
Not your income — your actual spending. What do you need each year to live at your desired lifestyle?

Step 2: Multiply by 25.

Examples:
• Annual spending $30,000 → FI Number: $750,000
• Annual spending $50,000 → FI Number: $1,250,000
• Annual spending $80,000 → FI Number: $2,000,000
• Annual spending $100,000 → FI Number: $2,500,000

**Adjusting for Social Security and Other Income**

If you expect Social Security income ($20,000/year) or pension income, subtract that from your annual spending need before calculating.

Annual spending $60,000 − $20,000 Social Security = $40,000 from portfolio × 25 = $1,000,000 needed

**The Savings Rate Variable**

How fast you reach your FI number depends almost entirely on your savings rate — the percentage of income you save.

Approximate years to FI from a zero starting point:
• Save 10%: ~40 years
• Save 20%: ~30 years
• Save 30%: ~25 years
• Save 50%: ~17 years
• Save 70%: ~10 years

Each additional percentage point of savings rate meaningfully accelerates the timeline.

**The Safe Withdrawal Rate Debate**

Some researchers argue 4% is too aggressive for 40–50 year retirement periods (common for early retirees). A 3.5% rate implies needing 28.6× expenses; a 3% rate implies 33× expenses.

Factors that suggest lower withdrawal rates:
• Retiring before 60 (longer time horizon)
• High fixed expenses
• Low risk tolerance

Factors allowing higher rates:
• Short expected retirement (70+)
• Social Security providing income
• Flexibility to reduce spending or earn some income when needed

**The First Step**

Track your actual spending for 3–6 months to establish your realistic FI number. Most people are surprised by the gap between perceived and actual spending. Knowing your number turns retirement from a vague future event into a specific, calculable goal.
    `
